 1	#!/usr/bin/env node
 2	
 3	/**
 4	 * build-personas.js — thin wrapper around @mistralys/persona-builder.
 5	 * All build logic is delegated to the library via the CLI binary.
 6	 * Usage: node scripts/build-personas.js [--check] [--strict] [--dry-run]
 7	 */
 8	
 9	import fs from 'fs';
10	import path from 'path';
11	import { execFileSync } from 'child_process';
12	import { createRequire } from 'module';
13	
14	const _require = createRequire(import.meta.url);
15	
16	const ROOT     = path.join(import.meta.dirname, '..');
17	const PERSONAS = path.join(ROOT, 'personas');
18	const CONFIG   = path.join(PERSONAS, 'persona-build.config.js');
19	const CLI      = path.join(PERSONAS, 'node_modules', '@mistralys', 'persona-builder', 'dist', 'cli.js');
20	
21	// --dry-run is accepted as a convenience alias for --check (same behaviour)
22	const CHECK  = process.argv.includes('--check') || process.argv.includes('--dry-run');
23	const STRICT = process.argv.includes('--strict');
24	
25	// Pre-build: clean output directories so stale/renamed files don't linger.
26	// Skipped in --check / --dry-run mode (read-only).
27	if (!CHECK) {
28	  const config = _require(CONFIG);
29	  const outputDirs = [];
30	  for (const suite of Object.values(config.suites)) {
31	    if (suite.outVscode)     outputDirs.push(suite.outVscode);
32	    if (suite.outClaudeCode) outputDirs.push(suite.outClaudeCode);
33	    if (suite.outputDirs) {
34	      for (const dir of Object.values(suite.outputDirs)) {
35	        outputDirs.push(dir);
36	      }
37	    }
38	  }
39	  for (const dir of outputDirs) {
40	    if (!fs.existsSync(dir)) continue;
41	    const files = fs.readdirSync(dir).filter(f => f.endsWith('.md'));
42	    for (const file of files) {
43	      fs.unlinkSync(path.join(dir, file));
44	    }
45	  }
46	}
47	
48	// Delegate build to the library CLI
49	const cliArgs = ['--config', CONFIG];
50	if (CHECK)  cliArgs.push('--check');
51	if (STRICT) cliArgs.push('--strict');
52	
53	try {
54	  execFileSync(process.execPath, [CLI, ...cliArgs], { stdio: 'inherit' });
55	} catch (err) {
56	  process.exit(err.status ?? 1);
57	}
58	
59	// Post-build: sync personas/package.json version from changelog (real builds only)
60	if (!CHECK) {
61	  const changelogPath = path.join(ROOT, 'personas', 'changelog.md');
62	  const pkgPath       = path.join(ROOT, 'personas', 'package.json');
63	  const changelog     = fs.readFileSync(changelogPath, 'utf8');
64	  const match         = changelog.match(/^## v(\d+\.\d+\.\d+)/m);
65	
66	  if (!match) {
67	    console.warn('[WARN] Could not extract version from personas/changelog.md — skipping package.json update.');
68	  } else {
69	    const newVersion = match[1];
70	    const pkg        = JSON.parse(fs.readFileSync(pkgPath, 'utf8'));
71	    if (pkg.version !== newVersion) {
72	      const oldVersion = pkg.version;
73	      pkg.version = newVersion;
74	      fs.writeFileSync(pkgPath, JSON.stringify(pkg, null, 2) + '\n', 'utf8');
75	      console.log(`Updated personas/package.json: ${oldVersion} → ${newVersion}`);
76	    } else {
77	      console.log(`personas/package.json already at v${newVersion} — no update needed.`);
78	    }
79	  }
80	}
81	
82	// Post-build: generate personas/name-mapping.json (real builds only)
83	if (!CHECK) {
84	  const metaDir = path.join(ROOT, 'personas', 'ledger', 'src', 'meta');
85	  const outPath = path.join(ROOT, 'personas', 'name-mapping.json');
86	
87	  // This list must stay in sync with the 9 ledger roles in shared/workflow-manifest.json.
88	  // When a new persona is added to the workflow, update this list accordingly.
89	  const PERSONA_FILES = [
90	    '1-planner.yaml',
91	    '2-project-manager.yaml',
92	    '3-developer.yaml',
93	    '4-qa.yaml',
94	    '5-security-auditor.yaml',
95	    '6-reviewer.yaml',
96	    '7-release-engineer.yaml',
97	    '8-documentation.yaml',
98	    '9-synthesis.yaml',
99	  ];

